  function legacyTime(value){const text=String(value||'');let match=text.match(/(?:^|·|\s)(\d{1,2}):(\d{2})/);if(match)return match[1].padStart(2,'0')+':'+match[2];match=text.match(/(\d{1,2})\s*(am|pm)/i);return match?String(Number(match[1])%12+(match[2].toLowerCase()==='pm'?12:0)).padStart(2,'0')+':00':''}
