    const form=host.querySelector('form'),initial=formSnapshot(form);actionDrafts.set(mountId,()=>$(mountId).querySelector('[data-action-editor]')===host&&!host.hidden&&host.querySelector('form')===form&&formSnapshot(form)!==initial);form.elements.title.focus();
