  page.innerHTML=`<div class="mw-breadcrumb"><button id="mw-back">← Back to record</button><span id="mw-context-name"></span></div>
  <div class="mw-heading"><div><div class="mw-eyebrow">Internal meeting record</div><h2 id="mw-title"></h2><p class="mw-help">Your notes, decisions and follow-ups in one place.</p></div><div class="row"><span id="mw-save-state" role="status" class="badge">Saved in session</span><button id="mw-version">Save version</button><button id="mw-correct-time" type="button" aria-describedby="mw-time-help">Record actual meeting time</button><button id="mw-save" type="button">Save</button><button id="mw-cancel" type="button">Cancel</button><button id="mw-delete" type="button">Delete</button></div></div>
  <p id="mw-time-help" class="mw-help">Actual meeting time corrects your time report when the meeting starts late, ends early or runs over. It does not change the scheduled time.</p><p class="mw-help">Details and notes autosave. Save keeps a checkpoint; Cancel restores these fields to when you opened the meeting or last clicked Save. Attendees, decisions, files and PBC requests save separately.</p><section id="mw-delete-confirm" class="panel" hidden aria-label="Delete meeting confirmation"><h3>Delete this meeting?</h3><p>The minutes, attendees, decisions, calendar entry and its recorded meeting time will be removed. Existing PBC requests, follow-ups and uploaded documents are retained.</p><button id="mw-delete-yes" type="button">Delete meeting</button><button id="mw-delete-no" type="button">Keep meeting</button></section><div class="mw-info panel"><div class="mw-form-grid"><label>Meeting title *<input id="mw-field-title" data-meeting-field="title" maxlength="200"></label><label>Date *<input id="mw-field-date" data-meeting-field="date" type="date"></label><label>Time (Singapore)<input id="mw-field-time" data-meeting-field="time" type="time"></label><label>Duration (minutes)<input id="mw-field-durationMinutes" data-meeting-field="durationMinutes" type="number" min="1" max="1440" step="1" value="60"></label><label>Meeting type<select id="mw-field-kind" data-meeting-field="kind"><option value="client">Client meeting</option><option value="internal">Internal project meeting</option></select></label><label>Record status<select id="mw-field-status" data-meeting-field="status"><option>Draft</option><option>Reviewed</option></select></label></div><section class="mw-attendees" aria-labelledby="mw-attendee-heading"><div class="mw-section-heading"><h3 id="mw-attendee-heading">Attendees <span id="mw-attendee-count" class="badge"></span></h3><button id="mw-add-attendee" type="button">+ Add attendee</button></div><div id="mw-attendee-list"></div><details id="mw-original-attendees" class="mw-log" hidden><summary>Original attendee notes</summary><p id="mw-original-attendee-text"></p></details><form id="mw-attendee-form" class="mw-inline-editor" hidden><h4 id="mw-attendee-form-heading">Add attendee</h4><label>Add an existing person (optional)<select id="mw-attendee-person"></select></label><p class="mw-help">Choose a contact or team member, or enter someone new. Changes here apply to this meeting only.</p><div class="mw-form-grid"><label>Name *<input id="mw-attendee-name" required maxlength="150" aria-describedby="mw-attendee-error"></label><label>Organisation / team<input id="mw-attendee-organisation" maxlength="150"></label><label>Meeting role<select id="mw-attendee-role"><option>Participant</option><option>Chair</option><option>Note-taker</option><option>Presenter</option></select></label><label>Attendance<select id="mw-attendee-attendance"><option>Not recorded</option><option>Expected</option><option>Attended</option><option>Absent</option></select></label></div><p id="mw-attendee-error" class="field-error" role="alert"></p><div class="row"><button type="submit">Save attendee</button><button id="mw-cancel-attendee" type="button">Cancel</button></div></form></section></div>
  <div class="mw-tabs" role="tablist" aria-label="Meeting sections"><button id="mw-tab-minutes" role="tab" data-meeting-tab="minutes" aria-controls="mw-panel-minutes" aria-selected="true">Minutes</button><button id="mw-tab-actions" role="tab" data-meeting-tab="actions" aria-controls="mw-panel-actions" aria-selected="false">Actions & PBC</button><button id="mw-tab-files" role="tab" data-meeting-tab="files" aria-controls="mw-panel-files" aria-selected="false">Files & history</button><button id="mw-tab-draft" role="tab" data-meeting-tab="draft" aria-controls="mw-panel-draft" aria-selected="false">Follow-up draft</button></div>
  <section id="mw-panel-minutes" role="tabpanel" aria-labelledby="mw-tab-minutes"><div class="mw-writing-grid"><div class="mw-main"><section class="panel"><div class="mw-section-heading"><h3>Discussion notes</h3><span class="mw-help">${window.PlannerAPI?.enabled?"Autosaved to your private server":"Autosaved in this session"}</span></div><details class="mw-agenda"><summary>Agenda / meeting objectives</summary><label class="sr-only" for="mw-field-agenda">Agenda</label><textarea id="mw-field-agenda" data-meeting-field="agenda" placeholder="What do you want to cover?"></textarea></details><label class="sr-only" for="mw-field-notes">Discussion notes</label><textarea id="mw-field-notes" data-meeting-field="notes" class="mw-notepad" placeholder="Capture the discussion here. You can organise decisions and actions as you go."></textarea></section><section class="panel"><div class="mw-section-heading"><h3>Decisions & scope requests</h3><button id="mw-add-decision">+ Add item</button></div><p class="mw-help">A request is not an agreed commitment. Record the distinction for your own reference.</p><div id="mw-decisions"></div><form id="mw-decision-form" class="mw-inline-editor" hidden><label>Decision / request *<textarea id="mw-decision-text" required></textarea></label><div class="mw-form-grid"><label>Type<select id="mw-decision-kind"><option>Decision</option><option>Scope request</option><option>Clarification</option></select></label><label>State<select id="mw-decision-status"><option>Proposed</option><option>Agreed in discussion</option><option>Needs clarification</option></select></label></div><div class="row"><button type="submit">Save item</button><button type="button" id="mw-cancel-decision">Cancel</button></div><p id="mw-decision-error" class="field-error" role="alert"></p></form></section></div><div class="mw-context panel"><section aria-labelledby="mw-pbc-heading"><div class="mw-section-heading"><h3 id="mw-pbc-heading">PBC requests</h3><button id="mw-pbc-add" type="button">+ Add PBC</button></div><p class="mw-help">Capture client requests while writing. Saved requests also appear in the project’s PBC list.</p><div id="mw-pbc-list"></div><form id="mw-pbc-form" hidden><label>Request *<input id="mw-pbc-title" required maxlength="200"></label><label>Owner<input id="mw-pbc-owner" maxlength="160"></label><div class="mw-form-grid"><label>Request date *<input id="mw-pbc-request-date" type="date" required></label><label>Due date<input id="mw-pbc-due" type="date"></label></div><label>Comment<textarea id="mw-pbc-comment" rows="3"></textarea></label><p id="mw-pbc-error" class="field-error" role="alert"></p><div class="row"><button type="submit">Save PBC</button><button id="mw-pbc-cancel" type="button">Cancel</button></div></form></section><h3>Keep in view</h3><p class="mw-help">Open actions across this record. Earlier commitments stay visible for the next discussion.</p><div id="mw-open-actions"></div><button id="mw-go-actions">Manage actions & PBC →</button><div class="mw-context-footer"><strong>Working from Word?</strong><p class="mw-help">${window.PlannerAPI?.enabled?"Use Files & history to download a Word template, upload completed notes and review extracted text.":"Attach your notes or screenshots under Files & history. Word extraction and Ollama are not connected in this prototype."}</p><button id="mw-go-files">Attach supporting files</button></div></div></div></section>
  <section id="mw-panel-actions" role="tabpanel" aria-labelledby="mw-tab-actions" hidden><div class="panel"><h3>Actions & PBC</h3><p class="mw-help">One shared list for this opportunity or project. Each action keeps its source meeting and follow-up history.</p><div id="mw-actions"></div></div></section>
  <section id="mw-panel-files" role="tabpanel" aria-labelledby="mw-tab-files" hidden><div class="mw-writing-grid"><section class="panel"><h3>Supporting files</h3><p class="mw-help">${window.PlannerAPI?.enabled?"Attach original notes and screenshots. Files are stored privately; review extracted Word text before appending it to your minutes.":"Attach original Word notes, screenshots or reference documents. Files stay in this browser session; their contents are not automatically ingested."}</p><label>Choose supporting files<input id="mw-file-input" type="file" multiple accept=".docx,.doc,.pdf,.png,.jpg,.jpeg,.webp,.txt"></label><div id="mw-files"></div><div class="mw-context-footer"><button id="mw-word-template" disabled>Download Word template</button><p class="mw-help">${window.PlannerAPI?.enabled?"Complete the Word template, upload it here, then choose Extract notes. Screenshots remain supporting evidence.":"Template generation is a planned step. You can already attach an existing Word document."}</p></div></section><section class="panel"><h3>Saved versions</h3><p class="mw-help">Save version captures the minutes, decisions and actions as they stand. Subsequent edits keep the earlier snapshot.</p><div id="mw-versions"></div></section></div></section>
  <section id="mw-panel-draft" role="tabpanel" aria-labelledby="mw-tab-draft" hidden><section class="panel"><div class="mw-section-heading"><h3>Prepare a follow-up</h3><button id="mw-build-draft">Build draft from minutes</button></div><p class="mw-help">A simple draft assembled from this meeting’s notes and the outstanding actions you select below. Review and edit before using it outside this internal workspace. ${window.PlannerAPI?.enabled?"AI drafts use the provider you select in Connections. Nothing is sent to clients automatically.":"Nothing is sent automatically; Ollama is not connected."}</p><fieldset class="mw-draft-selection"><legend>Include outstanding actions</legend><div id="mw-draft-actions"></div></fieldset><p id="mw-draft-refresh" class="mw-help" hidden>This replaces the draft text. <button id="mw-confirm-draft">Replace draft</button> <button id="mw-keep-draft">Keep my edits</button></p><label for="mw-field-draft">Editable follow-up draft</label><textarea id="mw-field-draft" data-meeting-field="draft" class="mw-notepad" placeholder="Build a draft when your minutes are ready, or write your own."></textarea><button id="mw-download-draft">Download draft (.txt)</button></section></section>
  <p id="mw-error" class="field-error" role="alert"></p><p class="mw-session">${window.PlannerAPI?.enabled?"Private meeting record · Check the workspace save status before closing.":"Prototype · Notes, actions and attachments persist while this page stays open. Reloading resets sample data."}</p>`;
  document.querySelector('main').append(page);
  function current(){return active&&meetingFor(active.context,active.id)}
  $('mw-correct-time').hidden=!bridge.correctTime;$('mw-correct-time').onclick=()=>bridge.correctTime?.(active.context,current());
  function open(context,id) {
    if(!mayLeaveMeeting())return;
    const owner=ensure(context),m=meetingFor(context,id);if(!m)return;
    active={context,id};savedFields=captureFields(m);$('mw-delete-confirm').hidden=true;$('mw-pbc-form').hidden=true;bridge.open(context);$('mw-context-name').textContent=owner.name+' / Meetings';$('mw-back').textContent='← Back to '+owner.name;
    $('mw-title').textContent=m.title;['title','date','time','agenda','notes','status','draft','durationMinutes','kind'].forEach(key=>$('mw-field-'+key).value=m[key]||(key==='durationMinutes'?60:key==='kind'?'client':''));
    $('mw-save-state').textContent=window.PlannerAPI?.enabled?'Record open':'Saved in session';$('mw-error').textContent='';$('mw-decision-form').hidden=true;$('mw-draft-refresh').hidden=true;
    attendeeBaseline=null;decisionBaseline=null;$('mw-attendee-form').hidden=true;renderAttendees();renderDecisions();renderContext();renderActions('mw-actions',context,id);renderFiles();renderVersions();renderDraftActions();setTab('minutes');$('mw-title').tabIndex=-1;$('mw-title').focus();
  }
  $('mw-save').onclick=async()=>{
    const m=current();if(!m)return;
    if(!$('mw-field-title').value.trim()||!/^\d{4}-\d{2}-\d{2}$/.test($('mw-field-date').value)){$('mw-error').textContent='Enter a meeting title and date.';return}
    const duration=Number($('mw-field-durationMinutes').value);if(!Number.isInteger(duration)||duration<1||duration>1440){$('mw-error').textContent='Enter a duration from 1 to 1440 whole minutes.';return}
    const checkpoint=captureFields(m);$('mw-save').disabled=true;
    try{if(window.PlannerAPI?.enabled&&!await window.PlannerAPI.whenSaved())throw new Error('The meeting could not be saved. Your changes remain here; retry when the workspace is connected.');if(current()===m){savedFields=checkpoint;$('mw-error').textContent='';$('mw-save-state').textContent='Meeting saved';bridge.toast('Meeting saved.')}}catch(error){$('mw-error').textContent=error.message}finally{$('mw-save').disabled=false}
  };
  $('mw-cancel').onclick=()=>{const m=current();if(!m||!savedFields)return;Object.assign(m,savedFields);editableFields.forEach(key=>$('mw-field-'+key).value=savedFields[key]);$('mw-title').textContent=m.title;bridge.meetingChanged?.(active.context,m);saved(true);$('mw-error').textContent='';bridge.toast('Meeting details and notes restored to the last Save checkpoint.');$('mw-field-notes').focus()};
  $('mw-delete').onclick=()=>{$('mw-delete-confirm').hidden=false;$('mw-delete-yes').focus()};
  $('mw-delete-no').onclick=()=>{$('mw-delete-confirm').hidden=true;$('mw-delete').focus()};
  $('mw-delete-yes').onclick=()=>{
    const m=current(),context=active.context,owner=ensure(context);if(!m)return;
    owner.deletedMeetingIds=[...new Set([...(owner.deletedMeetingIds||[]),m.id])];
    owner.meetingRecords.splice(owner.meetingRecords.indexOf(m),1);
    owner.actionItems.forEach(a=>{if(a.meetingId===m.id)a.meetingId=''});
    attendeeBaseline=null;decisionBaseline=null;actionDrafts.delete('mw-actions');$('mw-pbc-form').hidden=true;
    bridge.meetingDeleted?.(context,m);active=null;savedFields=null;window.PlannerAPI?.changed();bridge.changed(context);bridge.back(context);bridge.toast('Meeting deleted. PBC requests and follow-ups were retained.');
  };
  $('mw-pbc-add').onclick=()=>{if(!$('mw-pbc-form').hidden){$('mw-pbc-title').focus();return}$('mw-pbc-form').hidden=false;['title','owner','due','comment'].forEach(key=>$('mw-pbc-'+key).value='');$('mw-pbc-request-date').value=today();$('mw-pbc-error').textContent='';pbcBaseline=pbcSnapshot();$('mw-pbc-title').focus()};
  $('mw-pbc-cancel').onclick=()=>{$('mw-pbc-form').hidden=true;$('mw-pbc-title').value='';$('mw-pbc-add').focus()};
  $('mw-pbc-form').onsubmit=e=>{e.preventDefault();if(!window.PlannerValidation.form($('mw-pbc-form'),$('mw-pbc-error')))return;const title=$('mw-pbc-title').value.trim(),requestDate=$('mw-pbc-request-date').value,due=$('mw-pbc-due').value;if(!title||!requestDate){$('mw-pbc-error').textContent='Enter the request and request date.';return}if(due&&due<requestDate){$('mw-pbc-error').textContent='Due date must be on or after the request date.';return}const owner=ensure(active.context);owner.actionItems.push({id:uid('action'),title,owner:$('mw-pbc-owner').value.trim(),requestDate,due,status:'Open',kind:'PBC',meetingId:active.id,comment:$('mw-pbc-comment').value,history:[]});window.PBCExchange.ensureIds(owner);$('mw-pbc-form').hidden=true;$('mw-pbc-title').value='';sync(active.context);bridge.changed(active.context);window.PlannerAPI?.changed();renderContext();renderActions('mw-actions',active.context,active.id);renderDraftActions();$('mw-pbc-add').focus();bridge.toast('PBC request added to this meeting and the shared PBC list.');};
  function renderAttendees(){
    const m=current(),attendees=structuredAttendees(m);$('mw-attendee-count').textContent=attendees.length;
    const rows=[...attendees].sort((a,b)=>a[attendeeSort.key].localeCompare(b[attendeeSort.key],undefined,{sensitivity:'base'})*attendeeSort.direction);
    const fields=[['name','Name'],['organisation','Organisation / team'],['role','Role'],['attendance','Attendance']];
    $('mw-attendee-list').innerHTML=rows.length?'<table class="mw-attendee-table"><thead><tr>'+fields.map(([key,label])=>'<th scope="col" aria-sort="'+(attendeeSort.key===key?(attendeeSort.direction===1?'ascending':'descending'):'none')+'"><button type="button" data-attendee-sort="'+key+'">'+label+' <span aria-hidden="true">'+(attendeeSort.key===key?(attendeeSort.direction===1?'↑':'↓'):'↕')+'</span></button></th>').join('')+'<th scope="col"><span class="sr-only">Attendee controls</span></th></tr></thead><tbody>'+rows.map(a=>'<tr>'+fields.map(([key,label])=>'<td data-label="'+label+'" title="'+esc(a[key]||'Not recorded')+'">'+(key==='attendance'?'<span class="badge">'+esc(a[key])+'</span>':esc(a[key]||'Not recorded'))+'</td>').join('')+'<td data-label="Actions"><div class="row"><button type="button" data-attendee-edit="'+esc(a.id)+'" aria-label="Edit '+esc(a.name)+'">Edit</button><button type="button" data-attendee-remove="'+esc(a.id)+'" aria-label="Remove '+esc(a.name)+'">Remove</button></div></td></tr>').join('')+'</tbody></table>':'<p class="mw-empty">No attendees yet. Add team members, client contacts or another participant.</p>';
    $('mw-original-attendees').hidden=!m.attendeesOriginal;$('mw-original-attendee-text').textContent=m.attendeesOriginal||'';
  }
  function editAttendee(id){
    if(attendeeBaseline!==null&&!$('mw-attendee-form').hidden&&attendeeSnapshot()!==attendeeBaseline){bridge.toast('Save or cancel the current attendee first.');return}
    const existing=structuredAttendees(current()).find(a=>a.id===id),list=people();
    $('mw-attendee-form').dataset.edit=id||'';$('mw-attendee-form').hidden=false;$('mw-attendee-form-heading').textContent=existing?'Edit attendee':'Add attendee';
    $('mw-attendee-person').innerHTML='<option value="">Enter manually</option>'+['Team','Client contacts'].map(group=>'<optgroup label="'+group+'">'+list.filter(p=>p.group===group).map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.organisation)+'</option>').join('')+'</optgroup>').join('');
    $('mw-attendee-person').value=existing?.personId||'';$('mw-attendee-name').value=existing?.name||'';$('mw-attendee-organisation').value=existing?.organisation||'';$('mw-attendee-role').value=existing?.role||'Participant';$('mw-attendee-attendance').value=existing?.attendance||'Not recorded';$('mw-attendee-error').textContent='';attendeeBaseline=attendeeSnapshot();$('mw-attendee-name').focus();
  }
